  .description("List loaded models from your local LM Studio or vLLM server")
  .option("-e, --endpoint <url>", "Local LLM endpoint (default: $LOCAL_LLM_ENDPOINT)")
  .option("-k, --api-key <key>", "API key / token (default: $LOCAL_LLM_API_KEY)")
